package net.civeira.phylax.features.oauth.userinvitation.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.OffsetDateTime;
import java.util.Optional;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.SecretDigester;
import net.civeira.phylax.features.oauth.userinvitation.domain.gateway.InvitationStoreGateway;

/**
 * Cancels and refreshes invitations over {@code access_user_invitation} (task 2.2). Each change is
 * a single conditional update: only a pending invitation of the tenant is touched, so a cancelled
 * or accepted one stays as it is.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class InvitationStoreAdapter implements InvitationStoreGateway {

  private final DataSource source;
  private final SecretDigester digester;

  @Override
  public boolean cancel(String uid, String tenantUid) {
    String sql = "UPDATE access_user_invitation SET status = 'CANCELLED', version = version + 1"
        + " WHERE uid = ? AND tenant = ? AND status = 'PENDING'";
    try (Connection conn = source.getConnection();
        PreparedStatement stat = conn.prepareStatement(sql)) {
      stat.setString(1, uid);
      stat.setString(2, tenantUid);
      return stat.executeUpdate() == 1;
    } catch (SQLException ex) {
      throw new IllegalStateException("Unable to cancel an invitation", ex);
    }
  }

  @Override
  public Optional<RefreshData> refresh(String uid, String tenantUid, String rawToken,
      OffsetDateTime newExpiresAt) {
    String update = "UPDATE access_user_invitation SET token_hash = ?, expires_at = ?,"
        + " version = version + 1 WHERE uid = ? AND tenant = ? AND status = 'PENDING'";
    String read = "SELECT i.email, u.email FROM access_user_invitation i"
        + " LEFT JOIN access_user u ON u.uid = i.invited_by WHERE i.uid = ?";
    try (Connection conn = source.getConnection()) {
      try (PreparedStatement stat = conn.prepareStatement(update)) {
        stat.setString(1, digester.digest(rawToken));
        stat.setTimestamp(2, Timestamp.from(newExpiresAt.toInstant()));
        stat.setString(3, uid);
        stat.setString(4, tenantUid);
        if (stat.executeUpdate() != 1) {
          return Optional.empty();
        }
      }
      try (PreparedStatement stat = conn.prepareStatement(read)) {
        stat.setString(1, uid);
        try (ResultSet rs = stat.executeQuery()) {
          return rs.next()
              ? Optional.of(
                  new RefreshData(rs.getString(1), rs.getString(2) == null ? "" : rs.getString(2)))
              : Optional.empty();
        }
      }
    } catch (SQLException ex) {
      throw new IllegalStateException("Unable to refresh an invitation", ex);
    }
  }
}
